class Demo1
{
    int a = 10;

    void display()
    {
        System.out.println("This display is from Demo1");
    }
}

class Demo2 extends Demo1
{
    int a = 50;

    void display()
    {
        System.out.println("Child a = " + a);
        System.out.println("Parent a = " + super.a);
        super.display();
    }
}

class Demo1
{
    void display()
    {
        System.out.println("Parent display");
    }
}

class Demo2 extends Demo1
{
    void display()
    {
        super.display();
        System.out.println("Child display");
    }
}

final class SerpentEagle
{
    void fly()
    {
        System.out.println("Eagle is flying very high.");
    }
}

class Lion extends SerpentEagle
{
    // Compilation error
}

class Eagle
{
    final void fly()
    {
        System.out.println("Eagle is flying very high.");
    }
}

class SerpentEagle extends Eagle
{
    // fly() cannot be overridden here
}

class Bird
{
    void fly()
    {
        System.out.println("Bird is flying");
    }
}

class Eagle extends Bird
{
    void fly()
    {
        System.out.println("Eagle is flying very high.");
    }
}

class Sparrow extends Bird
{
    void fly()
    {
        System.out.println("Sparrow is flying very low.");
    }
}

class Student
{
    final int age = 20;

    void display()
    {
        System.out.println(age);
    }
}

class Bird
{
    static final int BIRD_AGE = 20;
}

